def transform(grid):
    h,w=len(grid),len(grid[0]); frame=grid[0][0]
    sep=next(c for c in range(w) if all(grid[r][c]==0 for r in range(h)))
    # Bands divided by solid frame rows (include separators in output).
    bands=[]; a=0
    for r in range(h):
        if all(grid[r][c]==frame for c in range(sep)):
            if r>a: bands.append((a,r))
            a=r+1
    if a<h: bands.append((a,h))
    # right-hand components; each is used in the band with the same shape after rotation/reflection.
    seen=set(); objs=[]
    for r in range(h):
      for c in range(sep+1,w):
       if grid[r][c] and (r,c) not in seen:
        col=grid[r][c]; stack=[(r,c)];seen.add((r,c)); pts=[]
        while stack:
         y,x=stack.pop();pts.append((y,x))
         for yy,xx in ((y+1,x),(y-1,x),(y,x+1),(y,x-1)):
          if 0<=yy<h and sep<xx<w and (yy,xx) not in seen and grid[yy][xx]==col:
           seen.add((yy,xx));stack.append((yy,xx))
        objs.append((col,pts))
    out=[row[:sep] for row in grid]
    for a,b in bands:
      holes={(r-a,c) for r in range(a,b) for c in range(sep) if grid[r][c]==0}
      # Find object whose normalized point shape equals the hole shape under D4 transforms.
      def norm(ps):
       my=min(y for y,x in ps); mx=min(x for y,x in ps); return frozenset((y-my,x-mx) for y,x in ps)
      target=None
      for i,(col,pts) in enumerate(objs):
       raw={(y,x-(sep+1)) for y,x in pts}
       variants=[]
       for k in range(8):
        p=[(y,x) for y,x in raw]
        for _ in range(k%4): p=[(x,-y) for y,x in p]
        if k>=4:p=[(y,-x) for y,x in p]
        variants.append(norm(p))
       if norm(holes) in variants: target=i;break
      if target is not None:
       col,pts=objs.pop(target)
       for r,c in holes: out[a+r][c]=col
    return out
